#include "catalog.h"

/* PNG */
static const wxString s_catalog_16_png = wxT("");

wxIcon ibValueMetaObjectCatalog::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectCatalog::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_catalog_16_png, wxSize(16, 16));

	return icon;
}